// Base64 SVG insurer logos, ported verbatim from Coverage_Projection_Studio.html's
// INSURER_LOGOS object, keyed by the exact PlanDef.insurer string.
export const INSURER_LOGOS: Record<string, string> = {
  'HDFC ERGO': 'data:image/svg+xml;base64,',
  'Care Health': 'data:image/svg+xml;base64,',
  'Aditya Birla': 'data:image/svg+xml;base64,',
  'Niva Bupa': 'data:image/svg+xml;base64,',

  // Term Insurance insurers (2026-09) — brand marks supplied by the team,
  // encoded the same way as the Health entries above.
  'Axis Max Life': 'data:image/svg+xml;base64,',
  'ICICI Prudential': 'data:image/svg+xml;base64,',
  'HDFC Life': 'data:image/svg+xml;base64,',
  'Bajaj Life': 'data:image/svg+xml;base64,',
};

/**
 * KB insurer categories are free-text, admin-typed names (via "Add New KB"),
 * not a fixed enum — so names like "Axis Max life" / "Hdfc Life" / "ICICI
 * Prudential Life" need to resolve to the canonical entries above ("Axis Max
 * Life" / "HDFC Life" / "ICICI Prudential") despite not matching them
 * character-for-character. Used for both INSURER_LOGOS and the KB page's
 * INSURER_ACCENT_COLOR map, which have the exact same free-text-name problem.
 *
 * Exact match wins first; otherwise the longest canonical key that's a
 * substring either-way of the (normalized) category name wins, so a more
 * specific name ("HDFC Life") isn't shadowed by a shorter unrelated one
 * ("HDFC ERGO").
 */
function normalizeInsurerName(name: string): string {
  return name.trim().toLowerCase().replace(/\s+/g, " ");
}

export function matchInsurerKey<T>(categoryName: string, map: Record<string, T>): T | undefined {
  if (map[categoryName] !== undefined) return map[categoryName];
  const normalized = normalizeInsurerName(categoryName);
  const keys = Object.keys(map).sort((a, b) => b.length - a.length);
  for (const key of keys) {
    const normalizedKey = normalizeInsurerName(key);
    if (normalized === normalizedKey || normalized.includes(normalizedKey) || normalizedKey.includes(normalized)) {
      return map[key];
    }
  }
  return undefined;
}
